79	Status KvCacheOperation::InferShapeDimCheck(const SVector<TensorDesc> &inTensorDescs) const
80	{
81	    if ((inTensorDescs.at(0).shape.dimNum != 2 &&  // 2: 2 dims
82	         inTensorDescs.at(0).shape.dimNum != 4) || // 4: 4 dims
83	        inTensorDescs.at(1).shape.dimNum != 1 ||   // 1: layerId 1: 1 dim
84	        inTensorDescs.at(2).shape.dimNum != 4 ||   // 2: past 4: 4 dims
85	        inTensorDescs.at(3).shape.dimNum != 1 ||   // 3: tokenOffest 1: 1 dim
86	        inTensorDescs.at(4).shape.dimNum != 1) {   // 4: seqLen 1: 1 dim
87	        ATB_LOG(ERROR) << "invalid intensor dimNums";
88	        return ERROR_INVALID_TENSOR_DIM_NUM;
89	    }
90	    int64_t hiddenSize = inTensorDescs.at(2).shape.dims[3]; // 2: past 3: 3rd dim
91	    if (inTensorDescs.at(2).dtype == ACL_FLOAT16) {         // 2: past
92	        if (hiddenSize % 16 != 0) {                         // 16: memory alignment
93	            ATB_LOG(ERROR) << "hiddenSizes a should be a multiple of 16";
94	            return ERROR_INVALID_TENSOR_DIM;
95	        }
96	    }
97	    if (inTensorDescs.at(2).dtype == ACL_INT8) { // 2: past
98	        if (hiddenSize % 32 != 0) {              // 32: memory alignment
99	            ATB_LOG(ERROR) << "hiddenSizes should be a multiple of 32";
100	            return ERROR_INVALID_TENSOR_DIM;
101	        }
102	    }
103	    int64_t batch = inTensorDescs.at(2).shape.dims[1];         // 2: past 1: 1st dim
104	    if (inTensorDescs.at(0).shape.dimNum == 2) {               // 2: new_kv 2维
105	        if (hiddenSize != inTensorDescs.at(0).shape.dims[1]) { // 1: 1st dim
106	            ATB_LOG(ERROR) << "hiddenSizes should be same";
107	            return ERROR_INVALID_TENSOR_DIM;
108	        }
109	    }
110	    if (inTensorDescs.at(0).shape.dimNum == 4) {                   // 2: new_kv 4维
111	        if (hiddenSize != inTensorDescs.at(0).shape.dims[2] *      // 2: 2nd dim
112	                              inTensorDescs.at(0).shape.dims[3]) { // 3: 3rd dim
113	            ATB_LOG(ERROR) << "hiddenSizes should be same";
114	            return ERROR_INVALID_TENSOR_DIM;
115	        }
116	    }
117	    if (batch != inTensorDescs.at(3).shape.dims[0] || // 3: tokenOffset
118	        batch != inTensorDescs.at(4).shape.dims[0]) { // 4: seqLen
119	        ATB_LOG(ERROR) << "batches should be same";
120	        return ERROR_INVALID_TENSOR_DIM;
121	    }
122	    return NO_ERROR;
123	}
