53	bool CommonParamCheck(const infer::PagedAttentionParam &opParam)
54	{
55	    if (opParam.headNum <= 0) {
56	        ATB_LOG(ERROR) << "headNum should be greater than zero!";
57	        return false;
58	    }
59	    if (opParam.kvHeadNum < 0) {
60	        ATB_LOG(ERROR) << "kvHeadNum should be no less than zero!";
61	        return false;
62	    }
63	    if (opParam.kvHeadNum != 0) {
64	        if (opParam.headNum % opParam.kvHeadNum != 0) {
65	            ATB_LOG(ERROR) << "headNum mod kvHeadNum should be zero";
66	            return false;
67	        }
68	    }
69	    return true;
70	}
