72	bool Ascend950ParamCheck(const infer::PagedAttentionParam &opParam)
73	{
74	    if (!CommonParamCheck(opParam)) {
75	        return false;
76	    }
77	    if (opParam.qkScale <= 0 || opParam.qkScale > 1) {
78	        ATB_LOG(ERROR) << "On Ascend950, param qkScale [" << opParam.qkScale << "] should be in range (0, 1]";
79	        return false;
80	    }
81	    if (opParam.quantType != infer::PagedAttentionParam::QuantType::TYPE_QUANT_UNQUANT) {
82	        ATB_LOG(ERROR) << "On Ascend950, param quantType [" << opParam.quantType << "] should be TYPE_QUANT_UNQUANT";
