145	bool DeviceParamCheck(const infer::PagedAttentionParam &opParam)
146	{
147	    if (opParam.maskType == infer::PagedAttentionParam::MaskType::MASK_TYPE_NORM_COMPRESS) {
148	        if (!GetSingleton<Config>().Is310P()) {
149	            ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS only supported on Atlas 300I Duo inference product";
150	            return false;
151	        }
152	        if (opParam.quantType != infer::PagedAttentionParam::QuantType::TYPE_QUANT_UNQUANT) {
153	            ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS does not support quantization";
154	            return false;
155	        }
156	    }
157	    if (!GetSingleton<Config>().Is910B()) {
158	        if (opParam.batchRunStatusEnable) {
159	            ATB_LOG(ERROR) << "dynamic batch only support Atlas 800I A2 inference product";
160	            return false;
161	        }
162	        if (opParam.compressType != infer::PagedAttentionParam::CompressType::COMPRESS_TYPE_UNDEFINED) {
163	            ATB_LOG(ERROR) << "head compress only support Atlas 800I A2 inference product";
164	            return false;
165	        }
166	        if (opParam.mlaVHeadSize > 0) {
167	            ATB_LOG(ERROR) << "mla mode only support Atlas 800I A2 inference product";
168	            return false;
169	        }
170	        if (opParam.quantType != atb::infer::PagedAttentionParam::QuantType::TYPE_QUANT_UNQUANT) {
171	            ATB_LOG(ERROR) << "quant feature only support Atlas 800I A2 inference product";
172	            return false;
173	        }
174	    }
175	    if (GetSingleton<Config>().Is910A()) {
176	        if (opParam.maskType == atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_SPEC ||
177	            opParam.maskType == atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_MASK_FREE) {
178	            ATB_LOG(ERROR) << "SPEC_MASK and MASK_FREE does not support Atlas 800 training product";
179	            return false;
180	        }
181	        if (opParam.calcType != atb::infer::PagedAttentionParam::CalcType::CALC_TYPE_UNDEFINED) {
182	            ATB_LOG(ERROR) << "SPEC feature does not support Atlas 800 training product";
183	            return false;
184	        }
185	        if (opParam.scaleType != atb::infer::PagedAttentionParam::ScaleType::SCALE_TYPE_TOR) {
186	            ATB_LOG(ERROR) << "logN feature does not support Atlas 800 training product";
187	            return false;
188	        }
189	        if (opParam.inputLayout != atb::infer::InputLayout::TYPE_BSND) {
190	            ATB_LOG(ERROR) << "BNSD feature does not support Atlas 800 training product";
191	            return false;
192	        }
193	    }
194	    return true;
195	}
