197	bool CompressParamCheck(const infer::PagedAttentionParam &opParam)
198	{
199	    if (opParam.compressType >= infer::PagedAttentionParam::CompressType::COMPRESS_TYPE_MAX ||
200	        opParam.compressType < infer::PagedAttentionParam::CompressType::COMPRESS_TYPE_UNDEFINED) {
201	        ATB_LOG(ERROR) << "compressType should be in the range of its enum value";
202	        return false;
203	    }
204	    if (opParam.compressType == infer::PagedAttentionParam::CompressType::COMPRESS_TYPE_KVHEAD_ROPE &&
205	        opParam.maskType != infer::PagedAttentionParam::MaskType::UNDEFINED) {
206	        ATB_LOG(ERROR) << "When compressType is set to COMPRESS_TYPE_KVHead_ROPE, maskType must be set to UNDEFINED.";
207	        return false;
208	    }
209	    if (opParam.compressType == infer::PagedAttentionParam::CompressType::COMPRESS_TYPE_KVHEAD_ROPE &&
210	        opParam.batchRunStatusEnable) {
211	        ATB_LOG(ERROR) << "When compressType is set to COMPRESS_TYPE_KVHEAD_ROPE,"
212	                       << "batchRunStatusEnable must be set to false.";
213	        return false;
214	    }
215	    return true;
216	}
