219	{
220	    if (opParam.calcType != infer::PagedAttentionParam::CalcType::CALC_TYPE_UNDEFINED) {
221	        if (opParam.batchRunStatusEnable) {
222	            ATB_LOG(ERROR) << "SPEC func does not support dynamic batch";
