226	            ATB_LOG(ERROR) << "SPEC func only support when compressType is COMPRESS_TYPE_UNDEFINED";
227	            return false;
228	        }
229	        if (GetSingleton<Config>().Is910B()) {
230	            if (opParam.mlaVHeadSize == 0 &&
231	                opParam.maskType != atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_NORM &&
232	                opParam.maskType != atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_SPEC) {
233	                ATB_LOG(ERROR) << "SPEC func only support norm mask and spec mask";
234	                return false;
235	            }
236	        } else {
237	            if (opParam.maskType != atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_SPEC &&
238	                opParam.maskType != atb::infer::PagedAttentionParam::MaskType::UNDEFINED &&
239	                opParam.maskType != atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_MASK_FREE &&
240	                opParam.maskType != atb::infer::PagedAttentionParam::MaskType::MASK_TYPE_NORM_COMPRESS) {
241	                ATB_LOG(ERROR) << "SPEC func only supports no mask, spec mask, mask free, or norm_compress";
242	                return false;
