333	            (opParam.maskType == infer::PagedAttentionParam::MaskType::MASK_TYPE_NORM ||
334	             opParam.quantType != infer::PagedAttentionParam::QuantType::TYPE_QUANT_UNQUANT ||
335	             opParam.batchRunStatusEnable)) {
336	            ATB_LOG(ERROR) << "spec does not support norm mask, quant and dynamic batch";
