339	        if (opParam.compressType != infer::PagedAttentionParam::CompressType::COMPRESS_TYPE_UNDEFINED) {
340	            ATB_LOG(ERROR) << "mla mode does not support compress mask";
341	            return false;
342	        }
343	        if (opParam.quantType == infer::PagedAttentionParam::QuantType::TYPE_DEQUANT_FUSION) {
344	            ATB_LOG(ERROR) << "mla mode does not support dequant_fusion";
345	            return false;
