352	            ATB_LOG(ERROR) << "mla mode only support BSND InputLayout";
353	            return false;
354	        }
355	        if (opParam.kvHeadNum != 1) {
356	            ATB_LOG(ERROR) << "kvHeadNum should be 1, mla mode only support MQA";
357	            return false;
358	        }
359	        if (opParam.mlaVHeadSize > 576) { // 576: MLA大小限制
360	            ATB_LOG(ERROR) << "mlaVHeadSize should be no greater than 576";
