380	            opIrKeySs << "QuantOffline";
381	        } else if (param_.quantType == infer::PagedAttentionParam::QuantType::TYPE_QUANT_QKV_ONLINE) {
382	            opIrKeySs << "QuantOnline";
383	        }
384	        if (param_.calcType == infer::PagedAttentionParam::CalcType::CALC_TYPE_SPEC) {
385	            opIrKeySs << "Qlens";
386	        }
