392	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
393	        if (param_.quantType == infer::PagedAttentionParam::QuantType::TYPE_QUANT_UNQUANT) {
394	            operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr("PagedAttentionOperationAscend950");
