400	                  << ", batchRunStatusEnable:" << param.batchRunStatusEnable << ", quantType:" << param.quantType
401	                  << ", outDataType:" << param.outDataType << ", hasQuantOffset:" << param.hasQuantOffset
402	                  << ", compressType:" << param.compressType << ", calcType:" << param.calcType
403	                  << ", scaleType:" << param.scaleType << ", inputLayout:" << param.inputLayout;
