408	uint32_t PagedAttentionOperation::GetInputNum() const
409	{
410	    uint32_t inputNumBase = IN_TENSOR_NUM;
411	    if (param_.maskType != atb::infer::PagedAttentionParam::UNDEFINED) {
412	        inputNumBase += 1; // need to input mask
413	    }
414	    if (param_.batchRunStatusEnable) {
415	        inputNumBase += 1; // need to input batchRunStatus
416	    }
417	    if (param_.quantType == infer::PagedAttentionParam::TYPE_DEQUANT_FUSION) {
418	        inputNumBase += 2; // 2: kDescale, vDescale
419	        if (param_.hasQuantOffset) {
420	            inputNumBase += 2; // 2: kOffset, vOffset
421	        }
422	    }
423	    if (param_.calcType == infer::PagedAttentionParam::CALC_TYPE_SPEC) {
424	        inputNumBase += 1; // 1: qSeqLen
425	    }
426	    if (param_.compressType == infer::PagedAttentionParam::COMPRESS_TYPE_KVHEAD_ROPE) {
427	        inputNumBase += 1; // 1: razorOffset
428	    }
429	    bool needQKVQuant = (param_.quantType == atb::infer::PagedAttentionParam::TYPE_QUANT_QKV_OFFLINE ||
430	                         param_.quantType == atb::infer::PagedAttentionParam::TYPE_QUANT_QKV_ONLINE);
431	    if (needQKVQuant) {
432	        inputNumBase += 2; // 2: kDescale, vDescale
433	        if (param_.quantType == atb::infer::PagedAttentionParam::TYPE_QUANT_QKV_OFFLINE) {
434	            inputNumBase += 1; // pScale
435	        }
436	    }
437	    if (param_.scaleType == infer::PagedAttentionParam::SCALE_TYPE_LOGN) {
438	        inputNumBase += 1; // 1: logN
439	    }
440	    if (param_.mlaVHeadSize > 0) {
441	        inputNumBase--;
442	    }
443	    return inputNumBase;
444	}
