452	                                               SVector<TensorDesc> &outTensorDescs) const
453	{
454	    outTensorDescs.at(0) = inTensorDescs.at(0);
455	    bool needQKVQuant = (param_.quantType == atb::infer::PagedAttentionParam::TYPE_QUANT_QKV_OFFLINE ||
456	                         param_.quantType == atb::infer::PagedAttentionParam::TYPE_QUANT_QKV_ONLINE);
457	    if (needQKVQuant) {
458	        outTensorDescs.at(0).dtype = param_.outDataType;
459	    }
460	    if (GetSingleton<Config>().Is910B()) {
461	        int64_t hiddenSizeValue = 0;
462	        if (param_.mlaVHeadSize > 0) {
463	            hiddenSizeValue = param_.mlaVHeadSize;
464	        } else {
465	            uint32_t hiddenSizeValuePos = inTensorDescs.at(2).shape.dimNum - 1;
466	            hiddenSizeValue = inTensorDescs.at(2).shape.dims[hiddenSizeValuePos]; // 2: valueTensor
467	        }
468	        uint32_t hiddenSizeOut = outTensorDescs.at(0).shape.dimNum - 1;
469	        outTensorDescs.at(0).shape.dims[hiddenSizeOut] = hiddenSizeValue;
470	    }
471	    return NO_ERROR;
