480	    if (param_.inputLayout == infer::InputLayout::TYPE_BNSD && GetSingleton<Config>().Is910B()) {
481	        st = InferShapeDimCheckBNSD910B(inTensorDescs);
482	    } else {
483	        st = InferShapeDimCheck(inTensorDescs);
484	    }
485	
486	    if (st != NO_ERROR) {
487	        return st;
488	    }
489	    return MaskFreeInferShapeCheck310P(inTensorDescs);
490	}
