492	Status PagedAttentionOperation::SetupCheckImpl(const SVector<Tensor> &inTensors,
493	                                               const SVector<Tensor> &outTensors) const
494	{
495	    Status st = NO_ERROR;
496	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
497	        SVector<TensorDesc> inTensorDescs = {};
498	        OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
499	        st = InTensorDescsCheck950(inTensorDescs);
