515	    if (param_.inputLayout == infer::InputLayout::TYPE_BSND) {
516	        st = SetupDimCheck(inTensors, outTensors);
517	    } else if (param_.inputLayout == infer::InputLayout::TYPE_BNSD && GetSingleton<Config>().Is910B()) {
518	        st = SetupDimCheckBNSD910B(inTensors, outTensors);
519	    }
520	
521	    if (st != NO_ERROR) {
522	        return st;
523	    }
524	    return MaskFreeSetupCheck310P(inTensors);
