527	Status PagedAttentionOperation::KVCacheDimCheck310P(const SVector<TensorDesc> &inTensorDescs) const
528	{
529	    if (inTensorDescs.at(1).shape.dims[3] != DIM_ALIGN_16_NZ) { // 1: keyCache 3: last dim
530	        ATB_LOG(ERROR) << "lastDim of KVCache should be 16";
531	        return ERROR_INVALID_TENSOR_DIM;
532	    }
533	    if (inTensorDescs.at(2).shape.dims[3] != DIM_ALIGN_16_NZ) { // 2: valueCache 3: last dim
534	        ATB_LOG(ERROR) << "lastDim of KVCache should be 16";
535	        return ERROR_INVALID_TENSOR_DIM;
536	    }
537	    int64_t blockSize = inTensorDescs.at(2).shape.dims[2]; // 2: valueCache 2: blockSize
538	    if (blockSize != inTensorDescs.at(1).shape.dims[2]) {  // 1: keyCache 2: blockSize
539	        ATB_LOG(ERROR) << "blocksize of KVCache should be same";
540	        return ERROR_INVALID_TENSOR_DIM;
541	    }
542	    int64_t kvHeadNum = param_.kvHeadNum > 0 ? param_.kvHeadNum : param_.headNum;
543	    // kvHeadNum is checked > 0 in CreateOperation
544	    int64_t headSize = inTensorDescs.at(1).shape.dims[1] * DIM_ALIGN_16_NZ / kvHeadNum;
545	    if (headSize % DIM_ALIGN_16_NZ != 0) {
546	        ATB_LOG(ERROR) << "head_size should align 16 when format of keycache is NZ";
547	        return ERROR_INVALID_TENSOR_DIM;
548	    }
549	    if (headSize > 256 || headSize * blockSize > 128 * 128) { // 256: 310p headSize大小限制  // 128: 大小限制
550	        ATB_LOG(ERROR) << "head_size of keyCache should be no greater than 256 and "
551	                       << "block_size * head_size should be no greater than 128 * 128";
552	        return ERROR_INVALID_TENSOR_DIM;
553	    }
554	    if (headSize != inTensorDescs.at(0).shape.dims[2]) { // 2: headSize
555	        ATB_LOG(ERROR) << "headSizes of query and keyCache should be same";
556	        return ERROR_INVALID_TENSOR_DIM;
557	    }
558	    return NO_ERROR;
559	}
