565	    if (param_.quantType == infer::PagedAttentionParam::TYPE_DEQUANT_FUSION ||
566	        (param_.calcType == infer::PagedAttentionParam::CALC_TYPE_SPEC && param_.mlaVHeadSize == 0) ||
567	        (needQKVQuant && param_.mlaVHeadSize == 0) || param_.scaleType == infer::PagedAttentionParam::SCALE_TYPE_LOGN ||
568	        param_.compressType != infer::PagedAttentionParam::COMPRESS_TYPE_UNDEFINED) {
569	        return true;
570	    }
