585	Status PagedAttentionOperation::KVCacheDimCheck910B(const SVector<TensorDesc> &inTensorDescs) const
586	{
587	    int64_t headSize = inTensorDescs.at(1).shape.dims[3]; // 1: keyCache 3: headSize
588	    if (headSize != inTensorDescs.at(0).shape.dims[2]) {  // 2: headSize
589	        ATB_LOG(ERROR) << "headSize of keyCache and query should be same";
590	        return ERROR_INVALID_TENSOR_DIM;
591	    }
592	    int64_t blockSize = inTensorDescs.at(1).shape.dims[1];   // 1: keyCache 1: 1st dim
593	    if (IsInMLAIncompatible()) {                             // 非mla情况
594	        if (headSize != inTensorDescs.at(2).shape.dims[3]) { // 2: valueCache dim 3: headSize
595	            ATB_LOG(ERROR) << "headSize of keyCache and valueCache should be same";
596	            return ERROR_INVALID_TENSOR_DIM;
597	        }
598	        if (headSize > 256 || headSize * blockSize > 128 * 128) { // 256: 310p headSize大小限制  // 128: 大小限制
599	            ATB_LOG(ERROR) << "head_size of keyCache should be no greater than 256 and "
600	                           << "block_size * head_size should be no greater than 128 * 128";
601	            return ERROR_INVALID_TENSOR_DIM;
602	        }
603	    } else {
604	        if (param_.mlaVHeadSize > headSize) {
605	            ATB_LOG(ERROR) << "mlaVHeadSize should be no greater than headSizeK";
606	            return ERROR_INVALID_TENSOR_DIM;
607	        }
608	        int64_t headSizeV = param_.mlaVHeadSize > 0 ? param_.mlaVHeadSize :
609	                                                      inTensorDescs.at(2).shape.dims[3]; // 2: valueCache 3: headSize
610	        if (headSize > 576 || headSizeV > 576) { // 576: 910b headSize大小限制 // 576: headSize大小限制
611	            ATB_LOG(ERROR) << "head_size of keyCache and ValueCache should be no greater than 576";
612	            return ERROR_INVALID_TENSOR_DIM;
613	        }
614	        if (param_.mlaVHeadSize > 0 && !MlaBatchSizeCheck(inTensorDescs)) {
615	            return ERROR_INVALID_TENSOR_DIM;
616	        }
617	        // 特殊场景支持blocksize 256
618	        bool blockSize256Check =
619	            param_.mlaVHeadSize > 0 && blockSize == 256 && param_.kvHeadNum == 1 && // 256: blockSize
620	            (param_.headNum == 16 || param_.headNum == 32) && headSize == 576 &&    // 16 32: headNum 576: headSize
621	            headSizeV == 512 &&                                                     // 512: headSizeV
622	            param_.calcType != infer::PagedAttentionParam::CalcType::CALC_TYPE_SPEC;
623	        if (blockSize256Check) {
624	            return NO_ERROR;
625	        }
626	        if (((headSize > 256 || headSizeV > 256) && blockSize > 128)) { // 128: mla blockSize大小限制 256：headsize阈值
627	            ATB_LOG(ERROR) << "blockSize should be no greater than 128 if headSize > 256";
628	            return ERROR_INVALID_TENSOR_DIM;
629	        }
630	    }
631	    return NO_ERROR;
632	}
