634	Status PagedAttentionOperation::KVCacheDimCheck(const SVector<TensorDesc> &inTensorDescs) const
635	{
636	    int64_t numBlocks = inTensorDescs.at(1).shape.dims[0]; // 1: keyCache
637	    int64_t blockSize = inTensorDescs.at(1).shape.dims[1]; // 1: keyCache 1: blockSize
638	    int64_t headNum = inTensorDescs.at(1).shape.dims[2];   // 1: keyCache 2: headNum
639	    if (param_.mlaVHeadSize == 0) {
640	        if (numBlocks != inTensorDescs.at(2).shape.dims[0]) { // 2: valueCache
641	            ATB_LOG(ERROR) << "numBlocks should be same";
642	            return ERROR_INVALID_TENSOR_DIM;
643	        }
644	        if (blockSize != inTensorDescs.at(2).shape.dims[1]) { // 2: valueCache 1: 1st dim
645	            ATB_LOG(ERROR) << "2nd dim of KVCache should be same";
646	            return ERROR_INVALID_TENSOR_DIM;
647	        }
648	        if (headNum != inTensorDescs.at(2).shape.dims[2]) { // 2: valueCache 1: 2: headNum
649	            ATB_LOG(ERROR) << "3rd dim of KVCache should be same";
650	            return ERROR_INVALID_TENSOR_DIM;
651	        }
652	    }
653	    Status st = NO_ERROR;
654	    if (!GetSingleton<Config>().Is910B()) {
655	        st = KVCacheDimCheck310P(inTensorDescs);
656	    } else {
657	        st = KVCacheDimCheck910B(inTensorDescs);
658	    }
659	    return st;
660	}
