662	Status PagedAttentionOperation::InferShapeDimCheck(const SVector<TensorDesc> &inTensorDescs) const
663	{
664	    uint32_t blockTablesPos = 3; // 3: blockTables
665	    uint32_t contextLensPos = 4; // 4: contextLens
666	    if (param_.mlaVHeadSize > 0) {
667	        blockTablesPos--;
668	        contextLensPos--;
669	    } else if (inTensorDescs.at(2).shape.dimNum != 4) { // 2: valueCache 4: 4 dims
670	        ATB_LOG(ERROR) << "invalid intensor2 dimNum";
671	        return ERROR_INVALID_TENSOR_DIM_NUM;
672	    }
673	    if (inTensorDescs.at(0).shape.dimNum != 3 ||              // 0: query 3: 3 dims
674	        inTensorDescs.at(1).shape.dimNum != 4 ||              // 1: keyCache 4: 4 dims
675	        inTensorDescs.at(blockTablesPos).shape.dimNum != 2 || // 2: 2 dims
676	        inTensorDescs.at(contextLensPos).shape.dimNum != 1) { // 1: 1 dim
677	        ATB_LOG(ERROR) << "invalid intensor dimNum";
678	        return ERROR_INVALID_TENSOR_DIM_NUM;
679	    }
680	    int64_t numTokens = inTensorDescs.at(0).shape.dims[0];
681	    if (param_.batchRunStatusEnable) {
682	        if (numTokens > inTensorDescs.at(blockTablesPos).shape.dims[0] || // 3: blockTables
683	            numTokens > inTensorDescs.at(contextLensPos).shape.dims[0]) { // 4: contextLens
684	            ATB_LOG(ERROR) << "numTokens in q should be no greater than blockTables and contextLens"
685	                           << " , and should be same as output";
686	            return ERROR_INVALID_TENSOR_DIM;
687	        }
688	    }
689	
690	    Status st = KVCacheDimCheck(inTensorDescs);
691	    if (st != NO_ERROR) {
692	        return st;
693	    }
694	    return NO_ERROR;
695	}
