697	Status PagedAttentionOperation::InferShapeDimCheckBNSD910B(const SVector<TensorDesc> &inTensorDescs) const
698	{
699	    if (inTensorDescs.at(0).shape.dimNum != 3 || // 0: query 3: 3rd dims
700	        inTensorDescs.at(1).shape.dimNum != 4 || // 1: keyCache 4: 4th dims
701	        inTensorDescs.at(2).shape.dimNum != 4 || // 2: valueCache 4: 4th dims
702	        inTensorDescs.at(3).shape.dimNum != 2 || // 3: blockTables 2: 2nd dims
703	        inTensorDescs.at(4).shape.dimNum != 1) { // 4: contestLens 1: 1st dim
704	        ATB_LOG(ERROR) << "invalid intensor dimNum";
705	        return ERROR_INVALID_TENSOR_DIM_NUM;
706	    }
707	    int64_t headSize = inTensorDescs.at(0).shape.dims[2];  // 0: query 2: 2nd dim
708	    int64_t numBlocks = inTensorDescs.at(1).shape.dims[0]; // 1: keyCache 0: 0th dim
709	    int64_t blockSize = inTensorDescs.at(1).shape.dims[2]; // 1: keyCache 2: 2nd dim
710	    if (headSize != inTensorDescs.at(1).shape.dims[3] ||   // 1: keyCache 3: 3rd dim
711	        headSize != inTensorDescs.at(2).shape.dims[3]) {   // 2: valueCache 3: 3rd dim
712	        ATB_LOG(ERROR) << "headSize should be same";
713	        return ERROR_INVALID_TENSOR_DIM;
714	    }
715	    if (numBlocks != inTensorDescs.at(2).shape.dims[0]) { // 2: valueCache 0: 0th dim
716	        ATB_LOG(ERROR) << "numBlocks should be same";
717	        return ERROR_INVALID_TENSOR_DIM;
718	    }
719	    if (blockSize != inTensorDescs.at(2).shape.dims[2]) { // 2: valueCache 2: 2nd dim
720	        ATB_LOG(ERROR) << "blockSizes should be same";
721	        return ERROR_INVALID_TENSOR_DIM;
722	    }
723	    return NO_ERROR;
724	}
