726	// Compressed causal mask for 310P (fixed [2048,2048] fp16). NZ encoding
727	// is [1, 128, 2048, 16] = (1, kvS/16, qS, 16).
728	static constexpr int64_t LONG_COMPRESS_LEN = 2048;
729	static constexpr int64_t LONG_COMPRESS_NZ_DIM1 = LONG_COMPRESS_LEN / 16;
730	
731	static Status CheckNormCompressMaskShape310P(const TensorDesc &maskDesc)
732	{
733	    if (maskDesc.dtype != ACL_FLOAT16) {
734	        ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS requires fp16 mask dtype";
735	        return ERROR_INVALID_TENSOR_DTYPE;
736	    }
737	    const auto dimNum = maskDesc.shape.dimNum;
738	    const auto &dims = maskDesc.shape.dims;
739	    if (maskDesc.format == ACL_FORMAT_FRACTAL_NZ) {
740	        if (dimNum != 4 || dims[0] != 1 || dims[1] != LONG_COMPRESS_NZ_DIM1 ||
741	            dims[2] != LONG_COMPRESS_LEN || dims[3] != 16) {
742	            ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS NZ mask must be [1," << LONG_COMPRESS_NZ_DIM1
743	                           << "," << LONG_COMPRESS_LEN << ",16]";
744	            return ERROR_INVALID_TENSOR_DIM;
745	        }
746	        return NO_ERROR;
747	    }
748	    bool ok2d = (dimNum == 2 && dims[0] == LONG_COMPRESS_LEN && dims[1] == LONG_COMPRESS_LEN);
749	    bool ok3d = (dimNum == 3 && dims[0] == 1 && dims[1] == LONG_COMPRESS_LEN && dims[2] == LONG_COMPRESS_LEN);
750	    bool ok4d = (dimNum == 4 && dims[0] == 1 && dims[1] == 1 && dims[2] == LONG_COMPRESS_LEN &&
751	                 dims[3] == LONG_COMPRESS_LEN);
752	    if (!(ok2d || ok3d || ok4d)) {
753	        ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS ND mask must be [" << LONG_COMPRESS_LEN
754	                       << "," << LONG_COMPRESS_LEN << "] / [1,..] / [1,1,..]";
755	        return ERROR_INVALID_TENSOR_DIM;
756	    }
757	    return NO_ERROR;
758	}
