760	Status PagedAttentionOperation::MaskFreeInferShapeCheck310P(const SVector<TensorDesc> &inTensorDescs) const
761	{
762	    if (param_.maskType == atb::infer::PagedAttentionParam::MASK_TYPE_NORM_COMPRESS) {
763	        if (!GetSingleton<Config>().Is310P()) {
764	            ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS only supported on Atlas 300I Duo inference product";
765	            return ERROR_INVALID_PARAM;
766	        }
767	        return CheckNormCompressMaskShape310P(inTensorDescs.at(5));
768	    }
769	    if (param_.maskType == atb::infer::PagedAttentionParam::MASK_TYPE_MASK_FREE) {
770	        if (GetSingleton<Config>().Is310P()) {
771	            if (inTensorDescs.at(5).shape.dimNum != 4) {
772	                ATB_LOG(ERROR)
773	                    << "When maskType is mask free on Altas 300I Duo inference products, mask dim num should be 4";
774	                return ERROR_INVALID_TENSOR_DIM;
775	            }
776	            if (inTensorDescs.at(5).shape.dims[0] != 1 || inTensorDescs.at(5).shape.dims[1] != 8 ||
777	                inTensorDescs.at(5).shape.dims[2] != 128 || inTensorDescs.at(5).shape.dims[3] != 16) {
778	                ATB_LOG(ERROR) << "When maskType is mask free on Altas 300I Duo inference products, mask dims should "
779	                                  "be [1,8,128,16]";
780	                return ERROR_INVALID_TENSOR_DIM;
781	            }
782	            size_t kBlockSize = inTensorDescs.at(1).shape.dims[2];
783	            size_t vBlockSize = inTensorDescs.at(2).shape.dims[2];
784	            if (kBlockSize != 128 || vBlockSize != 128) {
785	                ATB_LOG(ERROR) << "PagedAttentionOperation intensor1 and intensor2 dim2 should be 128.";
786	                return ERROR_INVALID_PARAM;
787	            }
788	        } else {
789	            ATB_LOG(ERROR) << "Only Altas 300I Duo inference products support mask free";
790	            return ERROR_INVALID_TENSOR_DIM;
791	        }
792	    }
793	    return NO_ERROR;
794	}
