796	Status PagedAttentionOperation::MaskFreeSetupCheck310P(const SVector<Tensor> &inTensor) const
797	{
798	    if (param_.maskType == atb::infer::PagedAttentionParam::MASK_TYPE_NORM_COMPRESS) {
799	        if (!GetSingleton<Config>().Is310P()) {
800	            ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS only supported on Atlas 300I Duo inference product";
801	            return ERROR_INVALID_PARAM;
802	        }
803	        return CheckNormCompressMaskShape310P(inTensor.at(5).desc);
804	    }
805	    if (param_.maskType == atb::infer::PagedAttentionParam::MASK_TYPE_MASK_FREE) {
806	        if (GetSingleton<Config>().Is310P()) {
807	            if (GetSingleton<Config>().Is310P() &&
808	                param_.maskType == atb::infer::PagedAttentionParam::MASK_TYPE_MASK_FREE) {
809	                if (inTensor.at(5).desc.shape.dimNum != 4) {
810	                    ATB_LOG(ERROR)
811	                        << "When maskType is mask free on Altas 300I Duo inference products, mask dim num should be 4";
812	                    return ERROR_INVALID_TENSOR_DIM;
813	                }
814	                if (inTensor.at(5).desc.shape.dims[0] != 1 || inTensor.at(5).desc.shape.dims[1] != 8 ||
815	                    inTensor.at(5).desc.shape.dims[2] != 128 || inTensor.at(5).desc.shape.dims[3] != 16) {
816	                    ATB_LOG(ERROR) << "When maskType is mask free on Altas 300I Duo inference products, mask dims "
817	                                      "should be [1,8,128,16]";
818	                    return ERROR_INVALID_TENSOR_DIM;
819	                }
820	            }
821	            if (inTensor.at(4).desc.shape.dimNum == 1) {
822	                size_t batch = inTensor.at(4).desc.shape.dims[0];
823	                int *k_seqlen_list = static_cast<int *>(inTensor[4].hostData);
824	                int *q_seqlen_list = static_cast<int *>(inTensor[6].hostData);
825	
826	                for (size_t i = 0; i < batch; i++) {
827	                    if (k_seqlen_list[i] < q_seqlen_list[i]) {
828	                        ATB_LOG(ERROR) << "PagedAttentionOperation intensor4[i] should bigger than intensor6[i].";
829	                        return ERROR_INVALID_PARAM;
830	                    }
831	                    if ((k_seqlen_list[i] - q_seqlen_list[i]) % 128 != 0) {
832	                        ATB_LOG(ERROR)
833	                            << "PagedAttentionOperation (intensor4[i] - item in intensor6[i]) % 128 should be 0. ";
834	                        return ERROR_INVALID_PARAM;
835	                    }
836	                }
837	            } else {
838	                ATB_LOG(ERROR) << "PagedAttentionOperation k_seqlen_list dims should be 1.";
839	                return ERROR_INVALID_PARAM;
840	            }
841	
842	            size_t kBlockSize = inTensor.at(1).desc.shape.dims[2];
843	            size_t vBlockSize = inTensor.at(2).desc.shape.dims[2];
844	            if (kBlockSize != 128 || vBlockSize != 128) {
845	                ATB_LOG(ERROR) << "PagedAttentionOperation intensor1 and intensor2 dim2 should be 128.";
846	                return ERROR_INVALID_PARAM;
847	            }
848	        } else {
849	            ATB_LOG(ERROR) << "Only Altas 300I Duo inference products support mask free";
850	            return ERROR_INVALID_TENSOR_DIM;
851	        }
852	    }
853	    return NO_ERROR;
854	}
