856	bool PagedAttentionOperation::BlockDimCheck(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
857	{
858	    int64_t numBlocks = inTensors.at(1).desc.shape.dims[0];                            // 1: keyCache
859	    int64_t numHeads = inTensors.at(0).desc.shape.dims[1];                             // 1: 1st dim
860	    int64_t blockSize = inTensors.at(1).desc.shape.dims[1];                            // 1: keyCache 1: 1st dim
861	    if (param_.mlaVHeadSize == 0 && numBlocks != inTensors.at(2).desc.shape.dims[0]) { // 2: valueCache
862	        ATB_LOG(ERROR) << GetLogPrefix() << "numBlocks should be same";
863	        return false;
864	    }
865	
866	    if (numHeads != outTensors.at(0).desc.shape.dims[1]) { // 1: 1st dim
867	        ATB_LOG(ERROR) << GetLogPrefix() << "numHeads should be same";
868	        return false;
869	    }
870	    if (param_.mlaVHeadSize == 0 && blockSize != inTensors.at(2).desc.shape.dims[1]) { // 2: valueCache 1: 1st dim
871	        ATB_LOG(ERROR) << GetLogPrefix() << "blockSizes should be same";
872	        return false;
873	    }
874	    return true;
875	}
