877	bool PagedAttentionOperation::RazorDimCheck(const SVector<Tensor> &inTensors) const
878	{
879	    int64_t numBlocks = inTensors.at(1).desc.shape.dims[0]; // 1: keyCache
880	    int64_t blockSize = inTensors.at(1).desc.shape.dims[1]; // 1: keyCache 1: 1st dim
881	    uint64_t dimRazor = 2;
882	    uint64_t indexReverse = (param_.scaleType == infer::PagedAttentionParam::SCALE_TYPE_LOGN) ? 2 : 1;
883	    if (param_.compressType == infer::PagedAttentionParam::COMPRESS_TYPE_KVHEAD_ROPE) {
884	        if (inTensors.at(inTensors.size() - indexReverse).desc.shape.dimNum != dimRazor) {
885	            ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
886	            return false;
887	        }
888	        if (numBlocks != inTensors.at(inTensors.size() - indexReverse).desc.shape.dims[0]) {
889	            ATB_LOG(ERROR) << GetLogPrefix() << "numBlocks should be same";
890	            return false;
891	        }
892	        if (blockSize != inTensors.at(inTensors.size() - indexReverse).desc.shape.dims[1]) {
893	            ATB_LOG(ERROR) << GetLogPrefix() << "blockSizes should be same";
894	            return false;
895	        }
896	    }
897	    return true;
898	}
