900	bool PagedAttentionOperation::LogNDimCheck(const SVector<Tensor> &inTensors) const
901	{
902	    if (param_.scaleType == infer::PagedAttentionParam::SCALE_TYPE_LOGN) {
903	        if (inTensors.at(inTensors.size() - 1).desc.shape.dimNum != 1) {
904	            ATB_LOG(ERROR) << GetLogPrefix() << "invalid logN intensor dimNum";
905	            return false;
906	        }
907	        uint32_t inputNumBase = IN_TENSOR_NUM;
908	        uint32_t batchLogNNum = inTensors.at(inTensors.size() - 1).desc.shape.dims[0];
909	        if (inTensors.at(inputNumBase - 1).desc.shape.dims[0] != batchLogNNum) {
910	            ATB_LOG(ERROR) << "intensor contextLens and intensor logn has different batch size";
911	            return false;
912	        }
913	        if (param_.maskType != atb::infer::PagedAttentionParam::UNDEFINED) {
914	            inputNumBase += 1; // need to input mask
915	        }
916	        if (param_.batchRunStatusEnable) {
917	            if (inTensors.at(inputNumBase).desc.shape.dims[0] != batchLogNNum) {
918	                ATB_LOG(ERROR) << "intensor batchRunStatus and intensor logn has different batch size";
919	                return false;
920	            }
921	        }
922	    }
923	    return true;
924	}
