926	Status PagedAttentionOperation::SetupDimCheck(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
927	{
928	    SVector<TensorDesc> inTensorDescs = {};
929	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
930	    Status st = InferShapeCheckImpl(inTensorDescs);
931	    if (st != NO_ERROR) {
932	        return st;
933	    }
934	    int64_t numTokens = inTensors.at(0).desc.shape.dims[0];
935	    if (param_.batchRunStatusEnable) {
936	        if (numTokens != outTensors.at(0).desc.shape.dims[0]) {
937	            ATB_LOG(ERROR) << GetLogPrefix() << "numTokens of outTensor should be the same as q";
938	            return ERROR_INVALID_TENSOR_DIM;
939	        }
940	    }
941	    int64_t targetHeadSize =
942	        param_.mlaVHeadSize > 0 ? param_.mlaVHeadSize : inTensors.at(2).desc.shape.dims[3]; // 2: valueCache 3: 3rd dim
943	    if (!GetSingleton<Config>().Is910B()) {
944	        targetHeadSize = inTensors.at(0).desc.shape.dims[2]; // 2: 2nd dim
945	    }
946	    if (targetHeadSize != outTensors.at(0).desc.shape.dims[2]) { // 2: 2nd dim
947	        ATB_LOG(ERROR) << "headSize of attnOut error! It should equal to " << targetHeadSize;
948	        return ERROR_INVALID_TENSOR_DIM;
949	    }
950	
951	    if (!BlockDimCheck(inTensors, outTensors)) {
952	        return ERROR_INVALID_TENSOR_DIM;
953	    }
954	
955	    if (!RazorDimCheck(inTensors)) {
956	        return ERROR_INVALID_TENSOR_DIM;
957	    }
958	
959	    if (!LogNDimCheck(inTensors)) {
960	        return ERROR_INVALID_TENSOR_DIM;
961	    }
962	    return NO_ERROR;
963	}
