965	Status PagedAttentionOperation::SetupDimCheckBNSD910B(const SVector<Tensor> &inTensors,
966	                                                      const SVector<Tensor> &outTensors) const
967	{
968	    if (inTensors.at(0).desc.shape.dimNum != 3 || // 0: query 3: 3 dims
969	        inTensors.at(1).desc.shape.dimNum != 4 || // 1: keyCache 4: 4 dims
970	        inTensors.at(2).desc.shape.dimNum != 4 || // 2: valueCache 4: 4 dims
971	        inTensors.at(3).desc.shape.dimNum != 2 || // 3: blockTables 2: 2 dims
972	        inTensors.at(4).desc.shape.dimNum != 1) { // 4:contestLens 1: 1 dim
