976	    int64_t headSize = inTensors.at(0).desc.shape.dims[2];  // 0: query 2: 2nd dim
977	    int64_t numBlocks = inTensors.at(1).desc.shape.dims[0]; // 1: keyCache 0: 0th dim
978	    int64_t blockSize = inTensors.at(1).desc.shape.dims[2]; // 1: keyCache 2: 2nd dim
979	    if (headSize != inTensors.at(1).desc.shape.dims[3] ||   // 1: keyCache 3: 3rd dim
980	        headSize != inTensors.at(2).desc.shape.dims[3] ||   // 2: valueCache 3: 3rd dim
981	        headSize != outTensors.at(0).desc.shape.dims[2]) {  // 3: 3rd dim 2: 2nd dim
982	        ATB_LOG(ERROR) << "headSizes should be same";
983	        return ERROR_INVALID_TENSOR_DIM;
984	    }
985	    if (numBlocks != inTensors.at(2).desc.shape.dims[0]) { // 2: valueCache 0: 0th dim
986	        ATB_LOG(ERROR) << "numBlocks should be same";
987	        return ERROR_INVALID_TENSOR_DIM;
988	    }
989	    if (blockSize != inTensors.at(2).desc.shape.dims[2]) { // 2: valueCache 2: 2nd dim
990	        ATB_LOG(ERROR) << "blockSize should be same";
991	        return ERROR_INVALID_TENSOR_DIM;
992	    }
993	    return NO_ERROR;
