1128	Status PagedAttentionOperation::InTensorDescsCheck950(const SVector<TensorDesc> &inTensorDescs) const
1129	{
1130	    size_t inTensorId = 0;
1131	    TensorDesc qTensorDesc = inTensorDescs.at(inTensorId++);
1132	    TensorDesc kCacheTensorDesc = inTensorDescs.at(inTensorId++);
1133	    TensorDesc vCacheTensorDesc = inTensorDescs.at(inTensorId++);
1134	    TensorDesc blockTablesTensorDesc = inTensorDescs.at(inTensorId++);
1135	    TensorDesc contextLensTensorDesc = inTensorDescs.at(inTensorId++);
1136	
1137	    if (!TensorCheck::IsTensorDescDimNumValid(qTensorDesc, 3)) {
1138	        ATB_LOG(ERROR) << "q dim num should be 3, but get " << qTensorDesc.shape.dimNum;
1139	        return ERROR_INVALID_TENSOR_DIM_NUM;
1140	    }
1141	    if (!TensorCheck::IsTensorDescDimNumValid(kCacheTensorDesc, 4)) {
1142	        ATB_LOG(ERROR) << "kCache dim num should be 4, but get " << kCacheTensorDesc.shape.dimNum;
1143	        return ERROR_INVALID_TENSOR_DIM_NUM;
1144	    }
1145	    if (!TensorCheck::IsTensorDescDimNumValid(vCacheTensorDesc, 4)) {
1146	        ATB_LOG(ERROR) << "vCache dim num should be 4, but get " << vCacheTensorDesc.shape.dimNum;
1147	        return ERROR_INVALID_TENSOR_DIM_NUM;
1148	    }
1149	    if (!TensorCheck::IsTensorDescDimNumValid(blockTablesTensorDesc, 2)) {
1150	        ATB_LOG(ERROR) << "blockTables dim num should be 2, but get " << blockTablesTensorDesc.shape.dimNum;
1151	        return ERROR_INVALID_TENSOR_DIM_NUM;
1152	    }
1153	    if (!TensorCheck::IsTensorDescDimNumValid(contextLensTensorDesc, 1)) {
1154	        ATB_LOG(ERROR) << "contextLens dim num should be 1, but get " << contextLensTensorDesc.shape.dimNum;
1155	        return ERROR_INVALID_TENSOR_DIM_NUM;
1156	    }
1157	    int64_t numTokens = qTensorDesc.shape.dims[0];
1158	    int64_t qHeadNum = qTensorDesc.shape.dims[1];
1159	    if (qHeadNum != param_.headNum) {
1160	        ATB_LOG(ERROR) << "q dim1 and param headNum should be equal";
1161	        return ERROR_INVALID_TENSOR_DIM;
1162	    }
1163	    int64_t kvHeadNum = kCacheTensorDesc.shape.dims[2];
1164	    if (kvHeadNum != param_.kvHeadNum) {
1165	        ATB_LOG(ERROR) << "k dim2 and param kvHeadNum should be equal";
1166	        return ERROR_INVALID_TENSOR_DIM;
1167	    }
1168	    int64_t headSizeK = kCacheTensorDesc.shape.dims[3];
1169	    int64_t headSizeV = vCacheTensorDesc.shape.dims[3];
1170	    if (headSizeK != headSizeV) {
1171	        ATB_LOG(ERROR) << "k dim3 and v dim3 should be equal";
1172	        return ERROR_INVALID_TENSOR_DIM;
1173	    }
1174	    int64_t qSeqLen = 1;
1175	    int64_t batch = numTokens / qSeqLen;
1176	    int64_t contextLensBatch = contextLensTensorDesc.shape.dims[0];
1177	    if (contextLensBatch != batch) {
1178	        ATB_LOG(ERROR) << "contextLens dim0 should be " << batch << ", but get " << contextLensBatch;
1179	    }
1180	    if (param_.quantType == infer::PagedAttentionParam::QuantType::TYPE_DEQUANT_FUSION) {
1181	        TensorDesc kDescaleTensorDesc = inTensorDescs.at(inTensorId++);
1182	        TensorDesc vDescaleTensorDesc = inTensorDescs.at(inTensorId++);
1183	        if (!TensorCheck::IsTensorDescDimNumValid(kDescaleTensorDesc, 1)) {
1184	            ATB_LOG(ERROR) << "kDescale dim num should be 1, but get " << kDescaleTensorDesc.shape.dimNum;
1185	            return ERROR_INVALID_TENSOR_DIM_NUM;
1186	        }
1187	        if (!TensorCheck::IsTensorDescDimNumValid(vDescaleTensorDesc, 1)) {
1188	            ATB_LOG(ERROR) << "vDescale dim num should be 1, but get " << vDescaleTensorDesc.shape.dimNum;
1189	            return ERROR_INVALID_TENSOR_DIM_NUM;
1190	        }
1191	    }
1192	    return NO_ERROR;
1193	}
1194	
1195	Status PagedAttentionOperation::InTensorsCheck950(const SVector<Tensor> &inTensors) const
1196	{
1197	    size_t inTensorId = 0;
1198	    Tensor qTensor = inTensors.at(inTensorId++);
1199	    Tensor kCacheTensor = inTensors.at(inTensorId++);
1200	    Tensor vCacheTensor = inTensors.at(inTensorId++);
1201	    Tensor blockTablesTensor = inTensors.at(inTensorId++);
1202	    Tensor contextLensTensor = inTensors.at(inTensorId++);
1203	    int64_t numTokens = qTensor.desc.shape.dims[0];
1204	    int64_t qSeqLen = 1;
1205	    int64_t batch = numTokens / qSeqLen;
1206	    int64_t numBlocks = kCacheTensor.desc.shape.dims[0];
1207	    int64_t blockSize = kCacheTensor.desc.shape.dims[1];
1208	    std::vector<int32_t> contextLens;
1209	    contextLens.resize(batch);
1210	    int32_t *contextLensTensorHostData = (int32_t *)contextLensTensor.hostData;
1211	    for (size_t i = 0; i < contextLens.size(); ++i) {
1212	        contextLens.at(i) = contextLensTensorHostData[i];
1213	    }
1214	    int64_t blockNumValid = 0;
1215	    for (int64_t i = 0; i < batch; i++) {
1216	        int32_t actualSeqKVPerBatch = contextLens.at(i);
1217	        int64_t blockNumPerBatch = (actualSeqKVPerBatch + blockSize - 1) / blockSize;
1218	        blockNumValid += blockNumPerBatch;
1219	    }
1220	    if (numBlocks < blockNumValid) {
1221	        ATB_LOG(ERROR) << "keyCache dim1 should not be smaller than " << blockNumValid << ", but get " << numBlocks;
1222	        return ERROR_INVALID_TENSOR_DIM;
1223	    }
1224	
1225	    (void)vCacheTensor;
1226	    (void)blockTablesTensor;
1227	    return NO_ERROR;
1228	}
1229	
1230	Status PagedAttentionOperation::OutTensorsCheck950(const SVector<Tensor> &outTensors) const
1231	{
1232	    if (!TensorCheck::IsTensorDescDimNumValid(outTensors.at(0).desc, 3)) {
1233	        ATB_LOG(ERROR) << "outTensor dim num should be 3, but get " << outTensors.at(0).desc.shape.dimNum;
1234	        return ERROR_INVALID_TENSOR_DIM_NUM;
1235	    }
1236	    return NO_ERROR;
1237	}
