43	template <> Status CreateOperation(const infer::ReshapeAndCacheParam &opParam, Operation **operation)
44	{
45	    if (operation == nullptr) {
46	        return ERROR_INVALID_PARAM;
47	    }
48	    OP_PARAM_RSV_CHECK(opParam);
49	    if (!GetSingleton<Config>().Is910B()) {
50	        if (opParam.compressType != infer::ReshapeAndCacheParam::CompressType::COMPRESS_TYPE_UNDEFINED) {
51	            ATB_LOG(ERROR) << "head compress only support Atlas 800I A2 inference product";
52	            return ERROR_INVALID_PARAM;
53	        }
54	        if (Mki::PlatformInfo::Instance().GetPlatformType() != Mki::PlatformType::ASCEND_950) {
55	            if (opParam.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_BYPASS) {
56	                ATB_LOG(ERROR) << "key_cache SISO only support Atlas 800I A2 inference product and Ascend950";
57	                return ERROR_INVALID_PARAM;
58	            }
59	        }
60	    }
61	    if (opParam.compressType < infer::ReshapeAndCacheParam::CompressType::COMPRESS_TYPE_UNDEFINED ||
62	        opParam.compressType > infer::ReshapeAndCacheParam::CompressType::COMPRESS_TYPE_KVHEAD_ROPE) {
63	        ATB_LOG(ERROR) << "wrong compress head";
64	        return ERROR_INVALID_PARAM;
65	    }
66	    if (opParam.kvCacheCfg < infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE ||
67	        opParam.kvCacheCfg > infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) {
68	        ATB_LOG(ERROR) << "wrong kvcache config";
69	        return ERROR_INVALID_PARAM;
70	    }
71	    if (opParam.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_BYPASS &&
72	        opParam.compressType != infer::ReshapeAndCacheParam::CompressType::COMPRESS_TYPE_UNDEFINED) {
73	        ATB_LOG(ERROR) << "key_cache SISO do not support compress func";
74	        return ERROR_INVALID_PARAM;
75	    }
76	    if (opParam.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE_NZ &&
77	        opParam.compressType != infer::ReshapeAndCacheParam::CompressType::COMPRESS_TYPE_UNDEFINED) {
78	        ATB_LOG(ERROR) << "Format NZ only supports compressType:COMPRESS_TYPE_UNDEFINED! ";
79	        return ERROR_INVALID_PARAM;
80	    }
81	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
82	        Status st = ReshapeAndCacheAclnnRunner::LoadAclnnFuncs();
83	        if (st != NO_ERROR) {
84	            ATB_LOG(ERROR) << "ReshapeAndCacheAclnnRunner load aclnn functions failed!";
