177	                                                const SVector<Tensor> &outTensors) const
178	{
179	    SVector<TensorDesc> inTensorDescs;
180	    for (size_t i = 0; i < inTensors.size(); i++) {
181	        inTensorDescs.push_back(inTensors.at(i).desc);
182	    }
183	
184	    if (GetSingleton<Config>().Is310B()) {
185	        if (inTensorDescs.at(IN_TENSOR_2_KEYCACHE).format != aclFormat::ACL_FORMAT_FRACTAL_NZ ||
186	            inTensorDescs.at(IN_TENSOR_3_VALUECACHE).format != aclFormat::ACL_FORMAT_FRACTAL_NZ) {
187	            ATB_LOG(ERROR) << GetLogPrefix() << "Cache format only support NZ";
188	            return ERROR_INVALID_PARAM;
189	        }
190	    }
191	
192	    Status st = NO_ERROR;
193	    if (param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_BYPASS) {
194	        st = DimCheckSISO(inTensorDescs);
195	    } else if (param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) {
196	        st = KVCacheDimCheck910BNZ(inTensorDescs);
197	    } else {
198	        st = DimCheck(inTensorDescs);
199	    }
200	    if (st != NO_ERROR) {
201	        return st;
202	    }
203	    uint32_t keyCacheIndex = (param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE ||
204	                                param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) ?
205	                                IN_TENSOR_2_KEYCACHE : IN_TENSOR_1_KEYCACHE_SISO;
206	    if (!TensorUtil::TensorDescEqual(inTensorDescs.at(keyCacheIndex), outTensors.at(0).desc) ||
207	        ((param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE ||
208	        param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) &&
209	        !TensorUtil::TensorDescEqual(inTensorDescs.at(IN_TENSOR_3_VALUECACHE), outTensors.at(1).desc))) {
210	        ATB_LOG(ERROR) << GetLogPrefix() << "intensor & outtensor descs should be same";
211	        return ERROR_INVALID_TENSOR_DIM;
212	    }
213	    ATB_LOG(DEBUG) << "outTensors Size:" << outTensors.size();
214	    return NO_ERROR;
