217	Status ReshapeAndCacheOperation::DimCheck(const SVector<TensorDesc> &inTensorDescs) const
218	{
219	    if (inTensorDescs.at(IN_TENSOR_0_KEY).shape.dimNum != 3 ||         // 0: key 3: 3 dims
220	        inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dimNum != 3 ||       // 1: value 3: 3 dims
221	        inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dimNum != 4 ||    // 2: keyCache 4: 4 dims
222	        inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dimNum != 4 ||  // 3: valueCache 4: 4 dims
223	        inTensorDescs.at(IN_TENSOR_4_SLOTMAPPING).shape.dimNum != 1) { // 4: slotMapping 1: 1 dim
224	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
225	        return ERROR_INVALID_TENSOR_DIM_NUM;
226	    }
227	    int64_t numTokens = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[0];      // 0: key
228	    int64_t numHead = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[1];        // 1: key num_head
229	    int64_t numBlocks = inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[0]; // 2: keyCache
230	    int64_t blockSizeIndex = is910b_ ? 1 : 2;
231	    int64_t blockSize = inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[blockSizeIndex]; // 2: keyCache
232	    if (numTokens != inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[0]) {                  // 1: value
233	        ATB_LOG(ERROR) << GetLogPrefix() << "numTokens should be same";
234	        return ERROR_INVALID_TENSOR_DIM;
235	    }
236	    if (numHead != inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[1]) { // 1: value numHead
237	        ATB_LOG(ERROR) << GetLogPrefix() << "numHead should be same";
238	        return ERROR_INVALID_TENSOR_DIM;
239	    }
240	    if (numBlocks != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[0]) { // 3: valueCache
241	        ATB_LOG(ERROR) << GetLogPrefix() << "numBlocks should be same";
242	        return ERROR_INVALID_TENSOR_DIM;
243	    }
244	    if (blockSize != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[blockSizeIndex]) { // 3: valueCache
245	        ATB_LOG(ERROR) << GetLogPrefix() << "blockSizes should be same";
246	        return ERROR_INVALID_TENSOR_DIM;
247	    }
248	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
249	        return KVCacheDimCheck910B(inTensorDescs);
250	    }
251	    return is910b_ ? KVCacheDimCheck910B(inTensorDescs) : KVCacheDimCheck310P(inTensorDescs);
252	}
