254	Status ReshapeAndCacheOperation::DimCheckSISO(const SVector<TensorDesc> &inTensorDescs) const
255	{
256	    if (inTensorDescs.at(IN_TENSOR_0_KEY_SISO).shape.dimNum != 3 ||         // 0: key 3: 3 dims
257	        inTensorDescs.at(IN_TENSOR_1_KEYCACHE_SISO).shape.dimNum != 4 ||    // 1: keyCache 4: 4 dims
258	        inTensorDescs.at(IN_TENSOR_2_SLOTMAPPING_SISO).shape.dimNum != 1) { // 2: slotMapping 1: 1 dim
259	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
260	        return ERROR_INVALID_TENSOR_DIM_NUM;
261	    }
262	    int64_t numTokens = inTensorDescs.at(IN_TENSOR_0_KEY_SISO).shape.dims[0];        // 0: numTokens dim
263	    int64_t kNumHead = inTensorDescs.at(IN_TENSOR_0_KEY_SISO).shape.dims[1];         // 1: numHead dim
264	    int64_t kheadSize = inTensorDescs.at(IN_TENSOR_0_KEY_SISO).shape.dims[2];        // 2: headSize dim
265	    if (numTokens != inTensorDescs.at(IN_TENSOR_2_SLOTMAPPING_SISO).shape.dims[0]) { // 0 : numTokens dim
266	        ATB_LOG(ERROR) << GetLogPrefix() << "The dim 0 of intensor0 and dim 0 of intensor2 should be same";
267	        return ERROR_INVALID_TENSOR_DIM;
268	    }
269	    if (kNumHead != inTensorDescs.at(IN_TENSOR_1_KEYCACHE_SISO).shape.dims[2]) { // 2 : kNumHead dim
270	        ATB_LOG(ERROR) << GetLogPrefix() << "The dim 1 of intensor0 and dim 2 of intensor1 should be same";
271	        return ERROR_INVALID_TENSOR_DIM;
272	    }
273	    if (kheadSize != inTensorDescs.at(IN_TENSOR_1_KEYCACHE_SISO).shape.dims[3]) { // 3 : kheadSize dim
274	        ATB_LOG(ERROR) << GetLogPrefix() << "The dim 2 of intensor0 and dim 3 of intensor1 should be same";
275	        return ERROR_INVALID_TENSOR_DIM;
276	    }
277	    return NO_ERROR;
278	}
279	
280	Status ReshapeAndCacheOperation::KVCacheDimCheck910B(const SVector<TensorDesc> &inTensorDescs) const
281	{
282	    int64_t kNumHead = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[1];    // 1: value
283	    int64_t vNumHead = inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[1];  // 1: value
284	    int64_t kheadSize = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[2];   // 2: headSize dim
285	    int64_t vheadSize = inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[2]; // 2: headSize dim
286	    if (param_.compressType != infer::ReshapeAndCacheParam::COMPRESS_TYPE_UNDEFINED) {
287	        if (kheadSize != inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[2]) { // 1: value 2: 2nd dim
288	            ATB_LOG(ERROR) << GetLogPrefix() << "head compress key and value headSizes should be same";
289	            return ERROR_INVALID_TENSOR_DIM;
290	        }
291	        if ((kheadSize != inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[3] ||    // 2: keyCache 3: headSize dim
292	             kheadSize != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[3])) { // 3: valueCache 3: headSize dim
293	            ATB_LOG(ERROR) << GetLogPrefix() << "head compress keyCache and valueCache headSizes should be same";
294	            return ERROR_INVALID_TENSOR_DIM;
295	        }
296	        if (inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[2] != 1 ||   // 2: keyCache 2: dim 2
297	            inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[2] != 1) { // 3: valueCache 2: dim 2
298	            ATB_LOG(ERROR) << GetLogPrefix() << "The dim 2 of head compress keyCache and valueCache should be 1";
299	            return ERROR_INVALID_TENSOR_DIM;
300	        }
301	        if (kheadSize % HEADSIZE_ALIGN != 0) {
302	            ATB_LOG(ERROR) << GetLogPrefix() << "head compress key and value headSizes must be a multiple of 32";
303	            return ERROR_INVALID_TENSOR_DIM;
304	        }
305	    }
306	    if (param_.compressType == infer::ReshapeAndCacheParam::COMPRESS_TYPE_UNDEFINED &&
307	        (kNumHead != inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[2] ||    // 2: keyCache
308	         vNumHead != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[2])) { // 3: valueCache
309	        ATB_LOG(ERROR) << GetLogPrefix() << "numHeads should be same";
310	        return ERROR_INVALID_TENSOR_DIM;
311	    }
312	    if (kheadSize != inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[3] ||   // 2: keyCache 3: 3rd dim
313	        vheadSize != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[3]) { // 3: valueCache 3: 3rd dim
314	        ATB_LOG(ERROR) << GetLogPrefix()
315	                       << "key and keycache headSize should be same, value and value cache headSize should be same";
316	        return ERROR_INVALID_TENSOR_DIM;
317	    }
318	    return NO_ERROR;
319	}
320	
321	Status ReshapeAndCacheOperation::KVCacheDimCheck910BNZ(const SVector<TensorDesc> &inTensorDescs) const
322	{
323	    if (inTensorDescs.at(IN_TENSOR_0_KEY).shape.dimNum != 3 ||         // 0: key 3: 3 dims
324	        inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dimNum != 3 ||       // 1: value 3: 3 dims
325	        inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dimNum != 4 ||    // 2: keyCache 4: 4 dims
326	        inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dimNum != 4 ||  // 3: valueCache 4: 4 dims
327	        inTensorDescs.at(IN_TENSOR_4_SLOTMAPPING).shape.dimNum != 1) { // 4: slotMapping 1: 1 dim
328	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
329	        return ERROR_INVALID_TENSOR_DIM_NUM;
330	    }
331	    if (inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[0] !=
332	        inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[0]) {     // 1:key value numTokens
333	        ATB_LOG(ERROR) << GetLogPrefix() << "numTokens should be same";
334	        return ERROR_INVALID_TENSOR_DIM;
335	    }
336	    if (inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[1] !=
337	        inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[1]) { // 1: key value numHead
338	        ATB_LOG(ERROR) << GetLogPrefix() << "numHead should be same";
339	        return ERROR_INVALID_TENSOR_DIM;
340	    }
341	    int64_t kNumHead = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[1];   // 1: value
342	    int64_t kHeadSize = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[2];   // 2: kheadSize dim
343	    int64_t VHeadSize = inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[2]; // 2: vheadSize dim
344	    int64_t vNumHead = inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[1]; // 1: value
345	    int64_t blockSize = inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[2]; // 2: keyCache; 2: blocksize
346	    if (blockSize != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[2]) { // 3: valueCache
347	        ATB_LOG(ERROR) << GetLogPrefix() << "blockSizes should be same";
348	        return ERROR_INVALID_TENSOR_DIM;
349	    }
350	    if (blockSize % DIM_ALIGN_16_NZ != 0) {
351	        ATB_LOG(ERROR) << GetLogPrefix() << "The blockSize of keyCache and valueCache should be 16-aligned";
352	        return ERROR_INVALID_TENSOR_DIM;
353	    }
354	    if (param_.compressType == infer::ReshapeAndCacheParam::COMPRESS_TYPE_UNDEFINED) {
355	        if (inTensorDescs.at(IN_TENSOR_0_KEY).dtype == ACL_INT8) { // key: int8   keyCache last_dim=32
356	            if (kNumHead * kHeadSize != inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[1] * BLOCK_SIZE_32_NZ ||
357	                inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[3] != BLOCK_SIZE_32_NZ) { // 3: last dim
358	                ATB_LOG(ERROR) << GetLogPrefix() << "int8 NZ format tensor dim should be\
359	                    aligned to 32 and keyCache last dim should be 32!";
360	                return ERROR_INVALID_TENSOR_DIM;
361	            }
362	        } else { // key: fp16/bf16   keyCache last_dim=16
363	            if (kNumHead * kHeadSize != inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[1] * BLOCK_SIZE_16_NZ ||
364	                inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[3] != BLOCK_SIZE_16_NZ) { // 3: last dim
365	                ATB_LOG(ERROR) << GetLogPrefix() << "fp16/bf16 NZ format tensor dim should be\
366	                aligned to 16 and keyCache last dim should be 16!";
367	                return ERROR_INVALID_TENSOR_DIM;
368	            }
369	        } // value valueCache
370	        if (vNumHead * VHeadSize != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[1] * BLOCK_SIZE_16_NZ ||
371	            inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[3] != BLOCK_SIZE_16_NZ) { // 3: last dim
372	            ATB_LOG(ERROR) << GetLogPrefix() << "NZ format tensor dim should be aligned to 16!";
373	            return ERROR_INVALID_TENSOR_DIM;
374	        }
375	    }
376	    return NO_ERROR;
377	}
378	
379	Status ReshapeAndCacheOperation::KVCacheDimCheck310P(const SVector<TensorDesc> &inTensorDescs) const
380	{
381	    int64_t kNumHead = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[1];   // 1: value
382	    int64_t headSize = inTensorDescs.at(IN_TENSOR_0_KEY).shape.dims[2];   // 2: headSize dim
383	    int64_t vNumHead = inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[1]; // 1: value
384	    int64_t blockSize = inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[2]; // 2: keyCache; 2: blocksize
385	    int64_t hiddenSizeK = kNumHead * headSize;
386	    int64_t hiddenSizeV = vNumHead * headSize;
387	
388	    if (headSize != inTensorDescs.at(IN_TENSOR_1_VALUE).shape.dims[2]) { // 1: value 2: 2nd dim
389	        ATB_LOG(ERROR) << GetLogPrefix() << "key and value headSizes should be same";
390	        return ERROR_INVALID_TENSOR_DIM;
391	    }
392	    if (blockSize % DIM_ALIGN_16_NZ != 0) {
393	        ATB_LOG(ERROR) << GetLogPrefix() << "The blockSize of keyCache and valueCache should be 16-aligned";
394	        return ERROR_INVALID_TENSOR_DIM;
395	    }
396	    if (param_.compressType == infer::ReshapeAndCacheParam::COMPRESS_TYPE_UNDEFINED) {
397	        if (hiddenSizeK != inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[1] * NZBLOCKSIZE ||   // 2: keyCache
398	            hiddenSizeV != inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[1] * NZBLOCKSIZE || // 3: valueCache
399	            inTensorDescs.at(IN_TENSOR_2_KEYCACHE).shape.dims[3] != NZBLOCKSIZE ||   // 2: keyCache 3: 3rd dim
400	            inTensorDescs.at(IN_TENSOR_3_VALUECACHE).shape.dims[3] != NZBLOCKSIZE) { // 3: valueCache 3: 3rd dim
401	            ATB_LOG(ERROR) << GetLogPrefix() << "NZ format tensor dim should be aligned to 16";
402	            return ERROR_INVALID_TENSOR_DIM;
403	        }
404	    }
405	
406	    return NO_ERROR;
407	}
408	
409	std::shared_ptr<Runner> ReshapeAndCacheOperation::CreateRunner(Context &context) const
410	{
411	    (void)context;
412	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
413	        if (param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_BYPASS) {
414	            ATB_LOG(INFO) << GetLogPrefix() << "create ReshapeAndCacheSisoAclnnRunner";
415	            return std::make_shared<ReshapeAndCacheSisoAclnnRunner>(param_);
416	        }
417	        ATB_LOG(INFO) << GetLogPrefix() << "create ReshapeAndCache AclnnRunner";
418	        return std::make_shared<ReshapeAndCacheAclnnRunner>(param_);
419	    }
420	    if (GetSingleton<Config>().Is910B()) {
421	        if (param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_BYPASS) {
422	            return std::make_shared<ReshapeAndCacheOpsRunnerSISO>(param_);
423	        } else if (param_.kvCacheCfg == infer::ReshapeAndCacheParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) {
424	            return std::make_shared<ReshapeAndCacheOpsRunnerA2NZ>(param_);
425	        } else {
426	            return std::make_shared<ReshapeAndCacheOpsRunner>(param_);
427	        }
428	    } else {
429	        /* NZ的场景 */
430	        return std::make_shared<ReshapeAndCacheOpsRunner310P>(param_);
431	    }
432	}
433	} // namespace atb
