55	    }
56	    OP_PARAM_RSV_CHECK(opParam);
57	    if (!GetSingleton<Config>().Is910B()) {
58	        ATB_LOG(ERROR) << "paged cache load only support Atlas 800I A2 inference product!";
59	        return ERROR_INVALID_PARAM;
60	    }
61	    if (opParam.kvCacheCfg < infer::PagedCacheLoadParam::KvCacheCfg::K_CACHE_V_CACHE_NZ ||
62	        opParam.kvCacheCfg > infer::PagedCacheLoadParam::KvCacheCfg::K_CACHE_V_CACHE_ND) {
63	        ATB_LOG(ERROR) << "wrong kvcache config";
64	        return ERROR_INVALID_PARAM;
65	    }
66	    if (opParam.kvCacheCfg == infer::PagedCacheLoadParam::KvCacheCfg::K_CACHE_V_CACHE_NZ &&
67	        (opParam.hasSeqStarts || opParam.isSeqLensCumsumMode)) {
68	        ATB_LOG(ERROR) << "foramt NZ donot support hasSeqStarts=true or isSeqLensCumsumMode=true!";
69	        return ERROR_INVALID_PARAM;
70	    }
71	    *operation = new (std::nothrow) PagedCacheLoadOperation(opParam);
72	    if (*operation == nullptr) {
73	        ATB_LOG(ERROR) << "failed to new operation";
74	        return ERROR_OUT_OF_HOST_MEMORY;
75	    }
76	    return NO_ERROR;
77	}
