121	    const SVector<Tensor> &outTensors) const
122	{
123	    SVector<TensorDesc> inTensorDescs;
124	    for (size_t i = 0; i < inTensors.size(); i++) {
125	        inTensorDescs.push_back(inTensors.at(i).desc);
126	    }
127	    if (param_.kvCacheCfg == infer::PagedCacheLoadParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) { // NZ
128	        if (outTensors.at(0).desc.shape.dims[1] !=
