134	        }
135	    } else if (outTensors.at(0).desc.shape.dims[1] != inTensorDescs.at(0).shape.dims[2] ||
136	                outTensors.at(0).desc.shape.dims[2] != inTensorDescs.at(0).shape.dims[3] ||
137	                outTensors.at(1).desc.shape.dims[1] != inTensorDescs.at(1).shape.dims[2] ||
138	                outTensors.at(1).desc.shape.dims[2] != inTensorDescs.at(1).shape.dims[3]) {
139	                ATB_LOG(ERROR) << GetLogPrefix() << "The last dimension of outTensors needs to remain aligned";
140	                return ERROR_INVALID_TENSOR_DIM;
141	    }
142	    Status st = DimCheck(inTensorDescs);
