149	Status PagedCacheLoadOperation::DimCheck(const SVector<TensorDesc> &inTensorDescs) const
150	{
151	    int64_t numBlocks = inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[0]; // 0: keyCache
152	    int64_t lencontext = inTensorDescs.at(IN_TENSOR_2_BLOCKTABLE).shape.dims[0]; // 2: blocktable
153	    int64_t sumcontext = inTensorDescs.at(IN_TENSOR_4_KEY).shape.dims[0]; // 4: key
154	    if (numBlocks != inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[0]) {
155	        ATB_LOG(ERROR) << GetLogPrefix() << "numBlocks should be same";
156	        return ERROR_INVALID_TENSOR_DIM;
157	    }
158	    if (sumcontext != inTensorDescs.at(IN_TENSOR_5_VALUE).shape.dims[0]) {
159	        ATB_LOG(ERROR) << GetLogPrefix() << "sumcontextlens should be same";
160	        return ERROR_INVALID_TENSOR_DIM;
161	    }
162	    if (param_.kvCacheCfg == infer::PagedCacheLoadParam::KvCacheCfg::K_CACHE_V_CACHE_ND) {
163	        int64_t blockSize = inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[BLOCKSIZEINDEX_ND]; // 1: keyCache
164	        int64_t num_heads = inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[BLOCKSIZEINDEX]; // 1: keyCache
165	        if (blockSize != inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[BLOCKSIZEINDEX_ND]) {
166	            ATB_LOG(ERROR) << GetLogPrefix() << "blockSizes should be same";
167	            return ERROR_INVALID_TENSOR_DIM;
168	        }
169	        if (num_heads != inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[BLOCKSIZEINDEX]) {
170	            ATB_LOG(ERROR) << GetLogPrefix() << "numHeads should be same";
171	            return ERROR_INVALID_TENSOR_DIM;
172	        }
173	        if (blockSize == ZERO) {
174	            ATB_LOG(ERROR) << GetLogPrefix() << "blockSize cannot be zero";
175	            return ERROR_INVALID_TENSOR_DIM;
176	        }
177	        if (param_.isSeqLensCumsumMode) {
178	            if (lencontext != inTensorDescs.at(IN_TENSOR_3_CONTEXTLENS).shape.dims[0] - ONE) { // 1:-1
179	                ATB_LOG(ERROR) << GetLogPrefix() <<
180	                    "the lencontext of blocktable should match the lencontext of SeqLens when isSeqLensCumsumMode is true.";
181	                return ERROR_INVALID_TENSOR_DIM;
182	            }
183	        } else if (lencontext != inTensorDescs.at(IN_TENSOR_3_CONTEXTLENS).shape.dims[0]) {
184	                    ATB_LOG(ERROR) << GetLogPrefix() <<
185	                        "the lencontext of blocktable should match the lencontext of SeqLens when isSeqLensCumsumMode is true.";
186	                    return ERROR_INVALID_TENSOR_DIM;
187	        }
188	    } else { // NZ
189	        int64_t blockSize = inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[BLOCKSIZEINDEX]; // 1: keyCache
190	        if (blockSize != inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[BLOCKSIZEINDEX]) {
191	            ATB_LOG(ERROR) << GetLogPrefix() << "blockSizes should be same";
192	            return ERROR_INVALID_TENSOR_DIM;
193	        }
194	        if (blockSize == ZERO) {
195	            ATB_LOG(ERROR) << GetLogPrefix() << "blockSize cannot be zero";
196	            return ERROR_INVALID_TENSOR_DIM;
197	        }
198	        if (blockSize % 16 != ZERO) {
199	            ATB_LOG(ERROR) << GetLogPrefix() << "blockSize must be aligned to 16";
200	            return ERROR_INVALID_TENSOR_DIM;
201	        }
202	        if (lencontext != inTensorDescs.at(IN_TENSOR_3_CONTEXTLENS).shape.dims[0]) {
203	            ATB_LOG(ERROR) << GetLogPrefix() << "lenscontextlens should be same";
204	            return ERROR_INVALID_TENSOR_DIM;
205	        }
206	    }
207	    return (param_.kvCacheCfg == infer::PagedCacheLoadParam::KvCacheCfg::K_CACHE_V_CACHE_NZ) ?
208	            KVCacheDimCheck910BNZ(inTensorDescs) : KVCacheDimCheck910BND(inTensorDescs);
209	}
210	
211	Status PagedCacheLoadOperation::KVCacheDimCheck910BNZ(const SVector<TensorDesc> &inTensorDescs) const
212	{
213	    if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dimNum != INPUTKEY_DIM ||     // 0: keyCache
214	        inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dimNum != INPUTVALUE_DIM || // 1: value Cache
215	        inTensorDescs.at(IN_TENSOR_2_BLOCKTABLE).shape.dimNum != INPUTBLOCK_DIM || // 2: dim=2
216	        inTensorDescs.at(IN_TENSOR_3_CONTEXTLENS).shape.dimNum != INPUTCONTEXTLENS_DIM || // 1: dim=1
217	        inTensorDescs.at(IN_TENSOR_4_KEY).shape.dimNum != INPUTBLOCK_DIM ||        // 2: dim=2
218	        inTensorDescs.at(IN_TENSOR_5_VALUE).shape.dimNum != INPUTBLOCK_DIM) {      // 2: dim=2
219	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
220	        return ERROR_INVALID_TENSOR_DIM_NUM;
221	    }
222	    if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).dtype == ACL_INT8) {
223	        if (inTensorDescs.at(IN_TENSOR_1_VALUECACHE).dtype == ACL_INT8) {
224	            if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[OUT_DIM] != THIRTYTWO ||
225	                inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[OUT_DIM] != THIRTYTWO) { // 1: valueCache
226	                ATB_LOG(ERROR) << GetLogPrefix() << "The last dimension of keycache and valuecache must be 32";
227	                return ERROR_INVALID_TENSOR_DIM;
228	            }
229	        } else {
230	            if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[OUT_DIM] != THIRTYTWO ||
231	                inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[OUT_DIM] != SIXTEEN) { // 1: valueCache
232	                ATB_LOG(ERROR) << GetLogPrefix() << "The last dimension of keycache must be 32 and valuecache must be 16";
233	                return ERROR_INVALID_TENSOR_DIM;
234	            }
235	        }
236	        if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[1] * THIRTYTWO > MAX_k ||
237	                inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[1] * THIRTYTWO > MAX_v) {
238	            ATB_LOG(ERROR) << GetLogPrefix() <<
239	                "numheads * headsize of keycache and valuecache must be less than 147456 Bytes!";
240	            return ERROR_INVALID_TENSOR_DIM;
241	        }
242	    } else  if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[OUT_DIM] != SIXTEEN ||
243	                inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[OUT_DIM] != SIXTEEN) { // 1: valueCache
244	            ATB_LOG(ERROR) << GetLogPrefix() << "The last dimension of keycache and valuecache must be 16";
245	            return ERROR_INVALID_TENSOR_DIM;
246	    } else if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[1] * THIRTYTWO > MAX_k ||
247	                inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[1] * THIRTYTWO > MAX_v) {
248	            ATB_LOG(ERROR) << GetLogPrefix() <<
249	                "numheads * headsize of keycache and valuecache must be less than 147456 Bytes!";
250	            return ERROR_INVALID_TENSOR_DIM;
251	    }
252	    return NO_ERROR;
253	}
254	
255	Status PagedCacheLoadOperation::KVCacheDimCheck910BND(const SVector<TensorDesc> &inTensorDescs) const
256	{
257	    if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dimNum != INPUTKEY_DIM || // 0: keyCache
258	        inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dimNum != INPUTVALUE_DIM || // 1: valueCache
259	        inTensorDescs.at(IN_TENSOR_2_BLOCKTABLE).shape.dimNum != INPUTBLOCK_DIM || // 2: blockTable
260	        inTensorDescs.at(IN_TENSOR_3_CONTEXTLENS).shape.dimNum != INPUTCONTEXTLENS_DIM || // 3: SeqLens
261	        inTensorDescs.at(IN_TENSOR_4_KEY).shape.dimNum != OUT_DIM || // 4:key
262	        inTensorDescs.at(IN_TENSOR_5_VALUE).shape.dimNum != OUT_DIM || // 5: value
263	        inTensorDescs.at(IN_TENSOR_6_SEQ_STARTS).shape.dimNum != INPUTCONTEXTLENS_DIM) { // 6: seq start
264	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
265	        return ERROR_INVALID_TENSOR_DIM_NUM;
266	    }
267	    int64_t num_heads = inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[NUM_HEADS_INDEX]; // 2: num heads
268	    int64_t head_size_k = inTensorDescs.at(IN_TENSOR_0_KEYCACHE).shape.dims[HEAD_SIZE_INDEX]; // 3: head_size_k
269	    int64_t head_size_v = inTensorDescs.at(IN_TENSOR_1_VALUECACHE).shape.dims[HEAD_SIZE_INDEX]; // 3: head_size_v
270	    if (inTensorDescs.at(IN_TENSOR_0_KEYCACHE).dtype == ACL_INT8) { // keyCache: int8
271	        if (num_heads * head_size_k % ALIGN_INT8 != 0) {
272	            ATB_LOG(ERROR) << GetLogPrefix() << "int8 ND format num_heads*head_size_k should be aligned to 32!";
273	            return ERROR_INVALID_TENSOR_DIM;
274	        }
275	    } else if (num_heads * head_size_k % ALIGN_FP16_BF16 != 0) {  // keyCache: fp16/bf16
276	            ATB_LOG(ERROR) << GetLogPrefix() << "fp16/bf16 ND format num_heads*head_size_k should be aligned to 16!";
277	            return ERROR_INVALID_TENSOR_DIM;
278	    }
279	    if (inTensorDescs.at(IN_TENSOR_1_VALUECACHE).dtype == ACL_INT8) { // valueCache: int8
280	        if (num_heads * head_size_v % ALIGN_INT8 != 0) {
281	            ATB_LOG(ERROR) << GetLogPrefix() << "int8 ND format num_heads*head_size_v should be aligned to 32!";
282	            return ERROR_INVALID_TENSOR_DIM;
283	        }
284	    } else if (num_heads * head_size_v % ALIGN_FP16_BF16 != 0) { // valueCache: fp16/bf16
285	            ATB_LOG(ERROR) << GetLogPrefix() << "fp16/bf16 ND format num_heads*head_size_v should be aligned to 16!";
286	            return ERROR_INVALID_TENSOR_DIM;
287	    }
288	    int64_t lencontext = inTensorDescs.at(IN_TENSOR_2_BLOCKTABLE).shape.dims[0]; // 2: blockTable-batch(len(contextLens))
289	    int64_t seqstart = inTensorDescs.at(IN_TENSOR_6_SEQ_STARTS).shape.dims[0]; // 6: seq_start-batch(len(contextLens))
290	    if (param_.hasSeqStarts) {
291	        if (seqstart != lencontext) {
292	            ATB_LOG(ERROR) << GetLogPrefix() <<
293	                "the length of seq_startus should match lencontext when hasSeqStarts is true.";
294	            return ERROR_INVALID_TENSOR_DIM;
295	        }
296	    }
297	    return NO_ERROR;
298	}
299	
300	std::shared_ptr<Runner> PagedCacheLoadOperation::CreateRunner(Context &context) const
301	{
302	    (void)context;
303	    return std::make_shared<PagedCacheLoadOpsRunner>(param_);
304	}
